import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import {
  boundary,
  usageFixture,
  usageOwner,
  setGating,
} from "./fixtures/usage-worker";
import { databaseTestsEnabled } from "./helpers/foundation-db";
import { claimUsage, withUsageTransaction } from "@/lib/usage-ledger";
import { resolveUsagePeriods } from "@/lib/usage-periods";
import { createCampaign } from "@/lib/campaigns";
import {
  dispatchUsagePending,
  reconcileUsageOwner,
  reconcileUsageOwners,
} from "@/lib/usage-reconciliation";

describe.runIf(databaseTestsEnabled)("quota reconciliation", () => {
  let fixture: Awaited<ReturnType<typeof usageFixture>>;
  beforeAll(async () => {
    fixture = await usageFixture();
    await setGating(boundary.db, true);
  });
  afterAll(async () => {
    if (fixture) await fixture.close();
  });
  it("repairs counter drift and releases expired READY work only once", async () => {
    const f = await usageOwner(boundary.db);
    await createCampaign(f.user.id, await f.input());
    const at = new Date(Date.now());
    await boundary.db.usagePeriod.updateMany({
      where: { userId: f.user.id },
      data: { reserved: 9 },
    });
    const spy = vi.spyOn(console, "warn").mockImplementation(() => {});
    const result = await reconcileUsageOwner(
      f.user.id,
      new Date(+at + 86400001),
    );
    expect(result.drift).toBe(2);
    expect(spy).toHaveBeenCalledWith(expect.stringContaining("COUNTER_DRIFT"));
    expect(
      (
        await boundary.db.usagePeriod.findMany({ where: { userId: f.user.id } })
      ).every((p) => p.reserved === 0),
    ).toBe(true);
    expect(
      (await reconcileUsageOwner(f.user.id, new Date(+at + 86400002))).drift,
    ).toBe(0);
    spy.mockRestore();
  });
  it("alerts on an orphan without refunding it", async () => {
    const f = await usageOwner(boundary.db);
    await createCampaign(f.user.id, await f.input());
    await boundary.db.send.deleteMany({
      where: { campaign: { userId: f.user.id } },
    });
    const spy = vi.spyOn(console, "warn").mockImplementation(() => {});
    expect((await reconcileUsageOwner(f.user.id)).orphans).toBe(1);
    expect(
      (
        await boundary.db.usagePeriod.findMany({ where: { userId: f.user.id } })
      ).map((p) => p.reserved),
    ).toEqual([1, 1]);
    expect(spy).toHaveBeenCalledWith(
      expect.stringContaining("OUTSTANDING_ORPHAN"),
    );
    spy.mockRestore();
  });
  it("expires orphan claims without refunds and repairs orphan confirmation from a durable receipt", async () => {
    const f = await usageOwner(boundary.db);
    await createCampaign(f.user.id, await f.input());
    const send = await boundary.db.send.findFirstOrThrow({
      where: { campaign: { userId: f.user.id } },
    });
    const at = new Date(Date.now());
    await withUsageTransaction(boundary.db, f.user.id, (owner) =>
      claimUsage(owner, send.id, resolveUsagePeriods(f.user, at), true, at),
    );
    await boundary.db.send.deleteMany({
      where: { id: send.id, campaign: { userId: f.user.id } },
    });
    await reconcileUsageOwner(f.user.id, new Date(+at + 120001));
    expect(
      await boundary.db.usageReservation.findFirst({
        where: { userId: f.user.id },
      }),
    ).toMatchObject({ status: "UNCERTAIN", sendId: null });
    await boundary.db.deliveryReceipt.create({
      data: {
        userId: f.user.id,
        deliveryKey: send.id,
        recipientEmail: "[REDACTED_EMAIL]",
        createdAt: at,
        sentAt: at,
      },
    });
    await reconcileUsageOwner(f.user.id, new Date(+at + 120002));
    expect(
      await boundary.db.usageReservation.findFirst({
        where: { userId: f.user.id },
      }),
    ).toMatchObject({ status: "CONFIRMED", chargedAt: at });
    expect(
      (
        await boundary.db.usagePeriod.findMany({ where: { userId: f.user.id } })
      ).map((p) => [p.sent, p.reserved]),
    ).toEqual([
      [1, 0],
      [1, 0],
    ]);
  });
  it("repairs failed and stuck publication with new event IDs and the same reservation", async () => {
    const f = await usageOwner(boundary.db);
    await createCampaign(f.user.id, await f.input());
    const publish = vi
      .fn()
      .mockRejectedValueOnce(new Error("event boundary failed"))
      .mockResolvedValue({});
    const at = new Date(Date.now());
    await expect(dispatchUsagePending(f.user.id, publish, at)).rejects.toThrow(
      "QUEUE_PUBLICATION_FAILED",
    );
    expect(await dispatchUsagePending(f.user.id, publish, at)).toBe(0);
    expect(
      await dispatchUsagePending(f.user.id, publish, new Date(+at + 300001)),
    ).toBe(1);
    expect(publish.mock.calls[0][0][0].id).not.toBe(
      publish.mock.calls[1][0][0].id,
    );
    expect(publish.mock.calls[0][0][0].data).toEqual(
      publish.mock.calls[1][0][0].data,
    );
    expect(
      await dispatchUsagePending(f.user.id, publish, new Date(+at + 600002)),
    ).toBe(1);
    expect(
      await boundary.db.usageReservation.count({
        where: { userId: f.user.id },
      }),
    ).toBe(1);
  });
  it("continues to other owners after one publication fails", async () => {
    const a = await usageOwner(boundary.db),
      b = await usageOwner(boundary.db);
    await createCampaign(a.user.id, await a.input());
    await createCampaign(b.user.id, await b.input());
    const delivered: string[] = [];
    const result = await reconcileUsageOwners(async (events) => {
      if (events[0].data.userId === a.user.id)
        throw new Error("fixture unavailable");
      delivered.push(events[0].data.userId);
    });
    expect(result.failed).toBe(1);
    expect(delivered).toContain(b.user.id);
  });

  it("recovers failed publication on the next recovery pass without changing the reservation", async () => {
    const f = await usageOwner(boundary.db);
    await createCampaign(f.user.id, await f.input());
    const at = new Date(Date.now());
    const publish = vi
      .fn()
      .mockRejectedValueOnce(new Error("publication failed"));
    await expect(dispatchUsagePending(f.user.id, publish, at)).rejects.toThrow(
      "QUEUE_PUBLICATION_FAILED",
    );
    const original = publish.mock.calls[0][0][0];
    publish.mockResolvedValue({});
    await reconcileUsageOwners(publish, new Date(+at + 4 * 3600000));
    const recovered = publish.mock.calls
      .slice(1)
      .flatMap(([events]) => events)
      .find((event) => event.data.userId === f.user.id);
    expect(recovered).toMatchObject({
      name: original.name,
      data: original.data,
    });
    expect(recovered.id).not.toBe(original.id);
    expect(
      await boundary.db.usageReservation.count({
        where: { userId: f.user.id },
      }),
    ).toBe(1);
  });
});
